-- Fixed metadata only. No Auth rows, passwords, key values or token payloads.
select jsonb_build_object(
 'database',current_database(),'operator',current_user,
 'unrestricted_visibility',(select rolsuper or rolbypassrls from pg_roles where rolname=current_user),
 'migration_versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations),
 'issuer_role_exists',exists(select 1 from pg_roles where rolname='eps_mcp_issuer_owner'),
 'issuer_function_count',(select count(*)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='eps'and p.proname='mcp_custom_access_token_hook'),
 'issuer_policy_count',(select count(*)from pg_policies where(schemaname,tablename,policyname)in(('eps','mcp_oauth_resources','mcp_issuer_resource_lookup'),('public','app_capability_grants','mcp_issuer_capability_lookup'))),
 'all_roles',(select jsonb_agg(jsonb_build_object('name',rolname,'oid',oid,'login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)order by rolname)from pg_roles),
 'all_memberships',(select coalesce(jsonb_agg(jsonb_build_object('role',roleid::regrole::text,'member',member::regrole::text,'grantor',grantor::regrole::text,'role_oid',roleid,'member_oid',member,'grantor_oid',grantor,'admin',admin_option,'inherit',inherit_option,'set',set_option)order by roleid,member,grantor),'[]'::jsonb)from pg_auth_members),
 'settings',(select jsonb_build_object('template_version',template_version,'default_timezone',default_timezone,'row_version',row_version,'default_review_expiry_days',default_review_expiry_days)from eps.app_settings where singleton),
 'registry_count',(select count(*)from eps.mcp_oauth_resources),
 'effective_privileges',(select coalesce(jsonb_object_agg(r.rolname,jsonb_build_object(
  'schemas',(select coalesce(jsonb_object_agg(nspname,jsonb_build_object('usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE'))),'{}')from pg_namespace n where nspname not like'pg_%'and nspname<>'information_schema'),
  'functions',(select coalesce(jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('execute',has_function_privilege(r.oid,p.oid,'EXECUTE'),'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'))),'{}')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and p.prokind='f'),
  'tables',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname,jsonb_build_object('select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,c.oid,'TRIGGER'),'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'))),'{}')from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and c.relkind in('r','p','v','m','f')),
  'columns',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('select',has_column_privilege(r.oid,c.oid,a.attnum,'SELECT'),'insert',has_column_privilege(r.oid,c.oid,a.attnum,'INSERT'),'update',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE'),'references',has_column_privilege(r.oid,c.oid,a.attnum,'REFERENCES'))),'{}')from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like'pg_%'and n.nspname<>'information_schema'and c.relkind in('r','p','v','m','f')and a.attnum>0 and not a.attisdropped)
 )),'{}')from pg_roles r where r.rolname in('supabase_auth_admin','eps_mcp_issuer_owner','anon','authenticated','service_role','eps_mcp_session_owner','eps_settings_owner'))
)as context;
